function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message)}catch{modal('Copy this text',`<p class="small">Select the text below and use your browser’s copy command.</p><textarea class="note-input" readonly aria-label="Text to copy">${esc(text)}</textarea>`);$('#panel textarea').select()}}
function absoluteLink(r){return location.href.split('#')[0]+'#'+r}
