document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a?.classList.contains('skip')){e.preventDefault();$('#main').focus();return}if(a?.dataset.anchor){e.preventDefault();$('#'+a.dataset.anchor)?.scrollIntoView({behavior:'auto',block:'start'});return}if(a&&a.getAttribute('href')?.startsWith('#')){if(!ready){e.preventDefault();toast('The sourcebook is still loading.');return}if(a.hash===location.hash){e.preventDefault();closeMenu();if($('#panel').open)closePanel();render()}else{positions.set(route,window.scrollY);closeMenu();if($('#panel').open)closePanel()}}
const b=e.target.closest('button');if(!b)return;const act=b.dataset.action;if(act==='menu'){toggleMenu();return}if(act==='close-menu'){closeMenu();$('[data-action=menu]').focus();return}if(act==='close-panel'){closePanel();return}if(!ready){toast('The sourcebook is still loading.');return}if(act==='search')search();if(act==='visuals')visuals();if(act==='jump')jump();if(act==='focus'){saved.prefs.mode=saved.prefs.mode==='focus'?'reading':'focus';persist();prefs()}if(act==='ar'||act==='en'){if(saved.prefs[act]&&!saved.prefs[act==='ar'?'en':'ar'])return toast('Keep at least one language visible.');saved.prefs[act]=!saved.prefs[act];persist();prefs()}if(act==='mark')toggleMark(route);if(b.dataset.mark)toggleMark(b.dataset.mark);if(act==='share')await copy(location.href,'Reading link copied.');if(b.dataset.share)await copy(absoluteLink(b.dataset.share),'Passage link copied.');if(b.dataset.copySource){const [t,id]=b.dataset.copySource.split('/'),r=(t==='matn'?M:E).get(id);await copy([r.title||r.chapter,r.arabic,r.english,r.source_line||'',absoluteLink(b.dataset.copySource)].filter(Boolean).join('\n\n'),'Passage and citation copied.')}if(b.dataset.note)note(b.dataset.note);if(b.dataset.saveNote){saved.notes[b.dataset.saveNote]=$('#note').value;persist();closePanel();toast('Reading note saved.');if(path==='desk')render(false)}if(b.dataset.unmark){saved.marks=saved.marks.filter(m=>m.route!==b.dataset.unmark);persist();render(false);toast('Bookmark removed.')}if(b.dataset.removeNote){const r=b.dataset.removeNote;modal('Remove this note?',`<p>This removes the note from this browser. Export your reading desk first if you want to keep a copy.</p><div class="actions"><button data-confirm-remove-note="${esc(r)}">Remove note</button><button data-action="close-panel">Keep note</button></div>`)}if(b.dataset.confirmRemoveNote){delete saved.notes[b.dataset.confirmRemoveNote];persist();closePanel();render(false);toast('Note removed.')}if(act==='export-desk')download('Tajrid_Reading_Desk.json',JSON.stringify(saved,null,2));if(act==='swap')sameRouteUpdate({left:$('#compare-right').value,right:$('#compare-left').value});if(act==='search-next'){searchPage++;updateSearch(false)}if(act==='search-prev'){searchPage--;updateSearch(false)}if(act==='reset-appearance'){saved.prefs={...saved.prefs,size:20,theme:'light',palette:'mineral',style:'quiet',layout:'parallel',fontAr:'Amiri',fontEn:'Georgia',order:'en'};persist();prefs();visuals()}});
