$('#scrim').addEventListener('click',closeMenu);$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});$('#panel').addEventListener('cancel',()=>{if(modalInvoker?.isConnected)modalInvoker.focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();return}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.target.closest('input,textarea,select,[contenteditable=true]')&&!$('#panel').open&&ready){e.preventDefault();search()}if(e.key==='Tab'&&document.body.classList.contains('nav-open')){const f=$$('#navigation a,#navigation button').filter(x=>x.getClientRects().length),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
